import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    try:
        network = IPv4Network(ip_range)
    except ValueError:
        raise ValueError("Invalid IP range")
    results = {}
    for ip in network.hosts():
        try:
            subprocess.run(['ping', '-c', '1', '-w', '1', str(ip)], check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True)
            results[str(ip)] = True
        except subprocess.CalledProcessError:
            results[str(ip)] = False
    return results

